    """The dedup identity of a bundle: claim, type, algorithm, and digest."""
    return (
        payload.claim_id,
        payload.evidence_type,
        payload.digest_algorithm,
        payload.digest_hex,
    )


def _evidence_bundle_identity_select(payload: EvidenceBundleCreate):
